// Weekly briefing: generated by the pipeline every Monday (templates only, no AI).
import { loadBriefing, loadBriefingIndex, loadDeals } from "../data.js";
import { date, esc, money } from "../format.js";
import { emptyState, toast } from "../ui.js";

const change = (pct) =>
  pct === null || pct === undefined
    ? `<span class="muted">n/a</span>`
    : `<span class="${pct >= 0 ? "delta-up" : "delta-down"}">${pct >= 0 ? "▲" : "▼"} ${Math.abs(pct).toFixed(0)}%</span>`;

function briefList(items, byId) {
  if (!items?.length) return emptyState("None this week.");
  return `<div class="deal-list">${items
    .map((b) => {
      const d = byId.get(b.id) || b;
      return `<a class="deal-item" href="#/deal/${encodeURIComponent(b.id)}">
        <span class="deal-co">${esc(d.company)}${d.ticker ? ` <span class="muted mono small">${esc(d.ticker)}</span>` : ""}</span>
        <span class="deal-amt">${money(d.amount ?? d.amount_sold, { estimate: d.amount_is_estimate })}</span>
        <span class="deal-sum">${esc(d.summary)}</span></a>`;
    })
    .join("")}</div>`;
}

export async function renderBriefing(root, weekParam) {
  const [index, { byId }] = await Promise.all([loadBriefingIndex(), loadDeals()]);
  const weeks = index.weeks || [];
  if (!weeks.length) {
    root.innerHTML = `<div class="page-head"><h1>Weekly Briefing</h1></div>${emptyState("The first briefing is generated on Monday.")}`;
    return;
  }
  const current = weeks.find((w) => w.week_start === weekParam) || weeks[0];
  const pos = weeks.indexOf(current);
  const b = await loadBriefing(current.week_start);
  const s = b.stats;
  const newer = weeks[pos - 1];
  const older = weeks[pos + 1];

  root.innerHTML = `
    <div class="page-head">
      <div><h1>Weekly Briefing</h1><p>Generated every Monday from the prior week's filings. Rule-based, no AI.</p></div>
      <div class="week-nav">
        <a class="btn btn-sm ${older ? "" : "disabled"}" ${older ? `href="#/briefing/${older.week_start}"` : 'aria-disabled="true"'}>← Older</a>
        <a class="btn btn-sm ${newer ? "" : "disabled"}" ${newer ? `href="#/briefing/${newer.week_start}"` : 'aria-disabled="true"'}>Newer →</a>
      </div>
    </div>

    <section class="briefing-hero">
      <div class="upper">Week of ${date(b.week_start)} – ${date(b.week_end)}</div>
      <h1>${esc(b.headline)}</h1>
      <div class="mini-stats">
        <div><div class="upper">Deals</div><div class="v">${s.deal_count}</div><div class="small">${change(b.change_vs_trailing.deal_count_pct)} vs 4-wk avg</div></div>
        <div><div class="upper">Raised (Form D)</div><div class="v">${money(s.capital_raised, { empty: "$0" })}</div><div class="small">${change(b.change_vs_trailing.capital_raised_pct)} vs 4-wk avg</div></div>
        <div><div class="upper">Funds raising</div><div class="v">${s.fund_count}</div><div class="small muted">pooled vehicles</div></div>
        <div><div class="upper">M&amp;A · Stakes</div><div class="v">${s.by_type["M&A"]} · ${s.by_type.Stake}</div><div class="small muted">${s.by_type["Material Agreement"]} material agmts</div></div>
      </div>
    </section>

    <section class="card">
      <div class="card-head"><h2>3 talking points for networking calls</h2><button class="btn btn-sm" id="copy-points" type="button">Copy</button></div>
      <div class="points">
        ${b.talking_points
          .map(
            (t) => `<div class="point"><div class="topic">${esc(t.topic)}</div><p>${esc(t.text)}</p>${
              t.deal_ids?.length
                ? `<div class="links">${t.deal_ids.map((id) => `<a href="#/deal/${encodeURIComponent(id)}">${esc(byId.get(id)?.company || "View deal")} →</a>`).join("")}</div>`
                : ""
            }</div>`,
          )
          .join("")}
      </div>
    </section>

    <div class="grid-2 even section-gap">
      <section class="card"><div class="card-head"><h2>Top deals by size</h2></div>${briefList(b.top_deals, byId)}</section>
      <section class="card"><div class="card-head"><h2>New fund raises</h2></div>${briefList(b.new_funds, byId)}</section>
      <section class="card"><div class="card-head"><h2>Notable M&amp;A and stakes</h2></div>${briefList(b.notable_ma, byId)}</section>
      <section class="card"><div class="card-head"><h2>Material agreements</h2></div>${briefList(b.material_agreements, byId)}</section>
    </div>

    <section class="card section-gap">
      <div class="card-head"><h2>Archive</h2><span class="muted small">${weeks.length} weeks</span></div>
      <div class="archive">
        ${weeks
          .map(
            (w) => `<a href="#/briefing/${w.week_start}" class="${w.week_start === current.week_start ? "current" : ""}">
              <span class="wk">${date(w.week_start, { year: false })}</span>
              <span class="hl">${esc(w.headline)}</span>
              <span class="mono small">${w.deal_count}</span></a>`,
          )
          .join("")}
      </div>
    </section>`;

  root.querySelector("#copy-points").addEventListener("click", async () => {
    const text = `Michigan Deal Radar: week of ${date(b.week_start)}\n\n` + b.talking_points.map((t, i) => `${i + 1}. ${t.topic}: ${t.text}`).join("\n\n");
    try {
      await navigator.clipboard.writeText(text);
      toast("Talking points copied");
    } catch {
      toast("Copy not available in this browser");
    }
  });
}
